function PublicationPreview({post,name}:{post:Post;name:string}){
  const [open,setOpen]=useState(false),[payload,setPayload]=useState<any[]|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState("");
  const media=(post.images||[]).map(i=>({src:scopedUrl(`/api/publications/${encodeURIComponent(post.id)}/images/${encodeURIComponent(i.id)}`,post.guildId),kind:i.kind||"image"}));
  async function toggle(){
    if(open){setOpen(false);return;}
    setOpen(true);
    if(payload)return;
    setBusy(true);setError("");
    try{const data=await api<{payload:any[]}>(`/publications/${encodeURIComponent(post.id)}/preview`);setPayload(data.payload);}
    catch(e){setError((e as Error).message);}
    finally{setBusy(false);}
  }
  return <div className="saved-publication-preview">
    {media.length>0?<div className="saved-photo-gallery">{media.map((item,index)=><SavedMedia key={item.src} src={item.src} index={index} kind={item.kind}/>)}</div>:<p className="saved-preview-note">Os arquivos desta publicação não estão mais disponíveis na prévia.</p>}
    <div className="saved-preview-toolbar"><span><Images size={14}/>{media.length?`${media.length} ${media.length===1?"arquivo":"arquivos"}`:"Publicação no Discord"}</span><button className="textbutton" aria-expanded={open} onClick={toggle}>{open?"Fechar prévia":"Ver prévia no Discord"}{open?<ChevronUp size={15}/>:<ChevronDown size={15}/>}</button></div>
    {open&&<div className="saved-discord-preview">{busy?<p role="status"><LoaderCircle className="spin" size={16}/>Carregando prévia…</p>:error?<p role="alert">{error}<button onClick={toggle}>Fechar</button></p>:payload&&<DiscordPreview payload={payload} photos={media} name={name}/>}<p className="saved-preview-note">A prévia usa os arquivos armazenados temporariamente no site.{post.url&&<> <a href={post.url} target="_blank" rel="noreferrer">Abrir publicação original <ArrowUpRight size={12}/></a></>}</p></div>}
  </div>;
}
